(43713,CONVERT(0x426f756d2e20436f6d6d656e7420c383c2a7612c2070617320646520626f756dc382c2a03f204a65207665757820756e20626f756dc382c2a02120424f554dc382c2a021204365747465207069c383c2a8636520646f697420c383c2aa7472652063617373c383c2a9652c206a65206d652064656d616e646520736920656c6c6520706f757272616974206578706c6f7365722e USING utf8mb4),_utf8mb4'Boom. Now boom? I wish for a boom. Boom go! This coin must be broken, I wonder if it''ll explode.'),
