-- Restore English base item descriptions; localized text is unchanged.
-- Match the previous text exactly so later custom edits are preserved.
CREATE TEMPORARY TABLE `item_english_text_fix` (
  `entry` INT UNSIGNED NOT NULL PRIMARY KEY,
  `old_description` TEXT CHARACTER SET utf8mb4 NOT NULL,
  `new_description` TEXT CHARACTER SET utf8mb4 NOT NULL
);
UPDATE `item_template` AS t
JOIN `item_english_text_fix` AS f ON f.`entry`=t.`entry`
SET t.`description`=f.`new_description`
WHERE BINARY t.`description`=BINARY f.`old_description`;
DROP TEMPORARY TABLE `item_english_text_fix`;
